package httpapi

import (
	"errors"
	"fmt"
	"testing"

	"github.com/jackc/pgx/v5/pgconn"
)

func cap64(value int64) *int64 { return &value }

func TestComputeDiscountAppliesPercentAndCap(t *testing.T) {
	discount, _, ok := computeDiscount(couponTerms{DiscountType: "percent", DiscountValue: 15}, 200_000)
	if !ok || discount != 30_000 {
		t.Fatalf("15%% 할인=%d ok=%v", discount, ok)
	}
	capped, _, ok := computeDiscount(couponTerms{DiscountType: "percent", DiscountValue: 50, MaxDiscountAmount: cap64(20_000)}, 200_000)
	if !ok || capped != 20_000 {
		t.Fatalf("상한 적용 할인=%d ok=%v", capped, ok)
	}
}

// A fixed coupon worth more than the order makes it free, never negative.
func TestComputeDiscountNeverExceedsTheOrder(t *testing.T) {
	discount, _, ok := computeDiscount(couponTerms{DiscountType: "fixed", DiscountValue: 500_000}, 80_000)
	if !ok || discount != 80_000 {
		t.Fatalf("할인=%d ok=%v", discount, ok)
	}
}

func TestComputeDiscountRejectsUnusableCombinations(t *testing.T) {
	cases := map[string]struct {
		terms  couponTerms
		amount int64
	}{
		"최소 주문 미달":   {couponTerms{DiscountType: "fixed", DiscountValue: 5_000, MinOrderAmount: 100_000}, 50_000},
		"알 수 없는 유형":  {couponTerms{DiscountType: "bogus", DiscountValue: 10}, 50_000},
		"비율 범위 초과":   {couponTerms{DiscountType: "percent", DiscountValue: 120}, 50_000},
		"할인이 0으로 내림": {couponTerms{DiscountType: "percent", DiscountValue: 1}, 50},
		"금액 없음":      {couponTerms{DiscountType: "fixed", DiscountValue: 1_000}, 0},
	}
	for name, testCase := range cases {
		if _, message, ok := computeDiscount(testCase.terms, testCase.amount); ok {
			t.Fatalf("%s: 거부되어야 합니다", name)
		} else if message == "" {
			t.Fatalf("%s: 거부 사유가 비어 있습니다", name)
		}
	}
}

func TestCouponInputValidation(t *testing.T) {
	in := couponInput{Code: " welcome10 ", Name: "신규 가입 할인", DiscountType: "percent", DiscountValue: 10}
	if message, ok := in.validate(); !ok {
		t.Fatalf("유효한 쿠폰이 거부되었습니다: %s", message)
	}
	if in.Code != "WELCOME10" {
		t.Fatalf("코드 정규화=%q", in.Code)
	}
	if in.PerUserLimit != 1 {
		t.Fatalf("1인 한도 기본값=%d", in.PerUserLimit)
	}
	bad := map[string]couponInput{
		"코드 공백": {Code: "AB CD", Name: "이름", DiscountType: "fixed", DiscountValue: 100},
		"코드 짧음": {Code: "AB", Name: "이름", DiscountType: "fixed", DiscountValue: 100},
		"유형 오류": {Code: "ABCD", Name: "이름", DiscountType: "half", DiscountValue: 10},
		"비율 초과": {Code: "ABCD", Name: "이름", DiscountType: "percent", DiscountValue: 101},
		"금액 0":  {Code: "ABCD", Name: "이름", DiscountType: "fixed", DiscountValue: 0},
		"한도 음수": {Code: "ABCD", Name: "이름", DiscountType: "fixed", DiscountValue: 10, PerUserLimit: -1},
	}
	for name, input := range bad {
		candidate := input
		if _, ok := candidate.validate(); ok {
			t.Fatalf("%s: 거부되어야 합니다", name)
		}
	}
}

// Only a unique violation means "that code is taken". Every other database
// failure has to stay distinguishable, or an outage gets reported as a
// duplicate and nobody goes looking for the real problem.
func TestIsUniqueViolationOnlyMatchesConstraintCollisions(t *testing.T) {
	if !isUniqueViolation(&pgconn.PgError{Code: "23505", ConstraintName: "coupons_code_key"}) {
		t.Fatal("23505는 중복으로 판정되어야 합니다")
	}
	// The pool returns wrapped errors, so unwrapping has to work.
	if !isUniqueViolation(fmt.Errorf("exec update: %w", &pgconn.PgError{Code: "23505"})) {
		t.Fatal("감싸인 23505도 중복으로 판정되어야 합니다")
	}
	notDuplicates := map[string]error{
		"검사 제약 위반":    &pgconn.PgError{Code: "23514"},
		"외래키 위반":      &pgconn.PgError{Code: "23503"},
		"not null 위반": &pgconn.PgError{Code: "23502"},
		"연결 끊김":       errors.New("conn closed"),
		"nil":         nil,
	}
	for name, err := range notDuplicates {
		if isUniqueViolation(err) {
			t.Fatalf("%s: 중복으로 판정되면 안 됩니다", name)
		}
	}
}

func TestGroupDigitsFormatsMoney(t *testing.T) {
	for value, want := range map[int64]string{0: "0", 999: "999", 1000: "1,000", 1234567: "1,234,567", -45000: "-45,000"} {
		if got := groupDigits(value); got != want {
			t.Fatalf("groupDigits(%d)=%q want %q", value, got, want)
		}
	}
}
package httpapi

import (
	"context"
	"errors"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

// isUniqueViolation reports whether a write failed because it collided with an
// existing row rather than for any other reason. Wherever the schema declares
// something unique — a coupon code, one open report per target — this is the
// difference between "that one is taken" and "the database is unwell", and
// callers used to report both as the same thing.
func isUniqueViolation(err error) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == "23505"
}

// couponTerms is the part of a coupon that decides the money, separated from
// storage so the arithmetic can be tested without a database.
type couponTerms struct {
	DiscountType      string
	DiscountValue     int64
	MinOrderAmount    int64
	MaxDiscountAmount *int64
}

// computeDiscount never returns more than the order amount, so a generous
// coupon can make an order free but can never make it negative.
func computeDiscount(terms couponTerms, amount int64) (int64, string, bool) {
	if amount <= 0 {
		return 0, "주문 금액을 확인해 주세요.", false
	}
	if amount < terms.MinOrderAmount {
		return 0, "이 쿠폰은 " + groupDigits(terms.MinOrderAmount) + "원 이상 주문에만 사용할 수 있습니다.", false
	}
	var discount int64
	switch terms.DiscountType {
	case "percent":
		if terms.DiscountValue <= 0 || terms.DiscountValue > 100 {
			return 0, "쿠폰 할인율이 올바르지 않습니다.", false
		}
		discount = amount * terms.DiscountValue / 100
	case "fixed":
		discount = terms.DiscountValue
	default:
		return 0, "지원하지 않는 쿠폰 유형입니다.", false
	}
	if terms.MaxDiscountAmount != nil && *terms.MaxDiscountAmount >= 0 && discount > *terms.MaxDiscountAmount {
		discount = *terms.MaxDiscountAmount
	}
	if discount > amount {
		discount = amount
	}
	if discount <= 0 {
		return 0, "이 주문에는 할인이 적용되지 않습니다.", false
	}
	return discount, "", true
}

// groupDigits formats an amount the way the messages show it to a buyer.
func groupDigits(value int64) string {
	text := strconv.FormatInt(value, 10)
	sign := ""
	if strings.HasPrefix(text, "-") {
		sign, text = "-", text[1:]
	}
	if len(text) <= 3 {
		return sign + text
	}
	var parts []string
	for len(text) > 3 {
		parts = append([]string{text[len(text)-3:]}, parts...)
		text = text[:len(text)-3]
	}
	return sign + text + "," + strings.Join(parts, ",")
}

type resolvedCoupon struct {
	ID       uuid.UUID
	Code     string
	Name     string
	Discount int64
}

// resolveCoupon checks the window, the switches and the usage limits inside the
// caller's transaction so two concurrent orders cannot both take the last use.
func resolveCoupon(ctx context.Context, tx pgx.Tx, code string, buyer uuid.UUID, amount int64) (resolvedCoupon, string, bool) {
	code = strings.ToUpper(strings.TrimSpace(code))
	if code == "" {
		return resolvedCoupon{}, "", true
	}
	var result resolvedCoupon
	var terms couponTerms
	var active bool
	var usageLimit *int32
	var perUser int32
	var startsAt, endsAt *time.Time
	err := tx.QueryRow(ctx, `SELECT id,code,name,discount_type,discount_value,min_order_amount,max_discount_amount,usage_limit,per_user_limit,starts_at,ends_at,active
		FROM coupons WHERE upper(code)=$1 FOR UPDATE`, code).
		Scan(&result.ID, &result.Code, &result.Name, &terms.DiscountType, &terms.DiscountValue, &terms.MinOrderAmount, &terms.MaxDiscountAmount,
			&usageLimit, &perUser, &startsAt, &endsAt, &active)
	if err != nil {
		return resolvedCoupon{}, "존재하지 않는 쿠폰 코드입니다.", false
	}
	now := time.Now()
	if !active {
		return resolvedCoupon{}, "사용이 중단된 쿠폰입니다.", false
	}
	if startsAt != nil && now.Before(*startsAt) {
		return resolvedCoupon{}, "아직 사용할 수 없는 쿠폰입니다.", false
	}
	if endsAt != nil && now.After(*endsAt) {
		return resolvedCoupon{}, "사용 기간이 지난 쿠폰입니다.", false
	}
	var total, mine int64
	if err := tx.QueryRow(ctx, `SELECT count(*),count(*) FILTER (WHERE user_id=$2) FROM coupon_redemptions WHERE coupon_id=$1`, result.ID, buyer).Scan(&total, &mine); err != nil {
		return resolvedCoupon{}, "쿠폰 사용 이력을 확인하지 못했습니다.", false
	}
	if usageLimit != nil && total >= int64(*usageLimit) {
		return resolvedCoupon{}, "쿠폰 사용 한도가 모두 소진되었습니다.", false
	}
	if perUser > 0 && mine >= int64(perUser) {
		return resolvedCoupon{}, "이 쿠폰을 사용할 수 있는 횟수를 모두 사용했습니다.", false
	}
	discount, message, ok := computeDiscount(terms, amount)
	if !ok {
		return resolvedCoupon{}, message, false
	}
	result.Discount = discount
	return result, "", true
}

// previewCoupon lets the order form show the real price before the buyer
// commits, using exactly the same rules the order will apply.
func (s *Server) previewCoupon(w http.ResponseWriter, r *http.Request) {
	p, _ := principalFrom(r.Context())
	var in struct {
		Code      string     `json:"code"`
		TalentID  uuid.UUID  `json:"talent_id"`
		PackageID *uuid.UUID `json:"package_id,omitempty"`
	}
	if !decodeJSON(w, r, &in) {
		return
	}
	if strings.TrimSpace(in.Code) == "" {
		writeError(w, 400, "code_required", "쿠폰 코드를 입력해 주세요.")
		return
	}
	tx, err := s.DB.Begin(r.Context())
	if err != nil {
		writeError(w, 500, "transaction_failed", "쿠폰을 확인하지 못했습니다.")
		return
	}
	defer tx.Rollback(r.Context()) //nolint:errcheck
	amount, err := orderAmount(r.Context(), tx, in.TalentID, in.PackageID)
	if err != nil {
		writeError(w, 404, "talent_not_found", "공개된 상품을 찾을 수 없습니다.")
		return
	}
	coupon, message, ok := resolveCoupon(r.Context(), tx, in.Code, p.UserID, amount)
	if !ok {
		writeError(w, 409, "coupon_not_applicable", message)
		return
	}
	writeJSON(w, 200, map[string]any{"code": coupon.Code, "name": coupon.Name, "amount": amount,
		"discount_amount": coupon.Discount, "payable_amount": amount - coupon.Discount})
}

// orderAmount is the list price of the chosen package, or the product's base
// price when no package is selected.
func orderAmount(ctx context.Context, tx pgx.Tx, talentID uuid.UUID, packageID *uuid.UUID) (int64, error) {
	var amount int64
	if err := tx.QueryRow(ctx, `SELECT t.base_price FROM talents t JOIN users u ON u.id=t.seller_id WHERE t.id=$1 AND t.status='published' AND u.status='active'`, talentID).Scan(&amount); err != nil {
		return 0, err
	}
	if packageID != nil {
		var packagePrice int64
		if err := tx.QueryRow(ctx, `SELECT price FROM talent_packages WHERE id=$1 AND talent_id=$2 AND active`, *packageID, talentID).Scan(&packagePrice); err != nil {
			return 0, err
		}
		amount = packagePrice
	}
	return amount, nil
}

type couponInput struct {
	Code              string     `json:"code"`
	Name              string     `json:"name"`
	DiscountType      string     `json:"discount_type"`
	DiscountValue     int64      `json:"discount_value"`
